@use "sass:math";

// Variables
$card-width-mobile: 85px;
$card-width: 150px;
// Primary box sizing
$primary-quick-link-base: 165px;
$primary-quick-link-base-mobile: 155px;
$primary-quick-link-base-min: 125px;
$primary-quick-link-base-min-mobile: 105px;
$gap-lg: 32px;
$gap-md: 24px;
$gap-sm: 16px;
$gap-xs: 8px;
$gap-compact: 4px;

// Sassy Map
$quicklink-icons: (
  advocacy,
  ambulance,
  book,
  books,
  career,
  check,
  discount,
  documents,
  event,
  gift,
  graduation,
  hospital,
  house,
  lightbulb,
  people,
  prescription,
  puzzle,
  saved,
  search,
  stethoscope,
  subscription,
  syringe,
);

// Icon Styles
@each $name in $quicklink-icons {
  %quick-link----#{$name} {
    display: inline-block;
    background-image: url("../icons/svg/quick-links/icon-#{$name}-purple.svg");
    background-repeat: no-repeat;

  }

  .quick-link--icon--#{$name} {
    @extend %quick-link----#{$name};
    background-size: 24px;
    width: 24px;
    height: 24px;

    @include breakpoint($bp-small) {
      background-size: 44px;
      width: 44px;
      height: 44px;
    }
  }

  .quick-link--icon--#{$name}--compact {
    @extend %quick-link----#{$name};
    background-size: 24px;
    width: 24px;
    height: 24px;
  }
}


// Placeholder Selectors
%item {
  background-color: $white;
  text-decoration: none;
  color: $black;
  cursor: pointer;
}

%label {
  color: $black;
  @include type($myriad-pro, 600);
  font-size: 16px;
  font-style: normal;
  line-height: normal;
  text-decoration: none;
}

%quick-links-hub {
  display: flex;
  gap: 21px;
  flex-direction: column;
  background: white;
  border-radius: 8px;
  border: 1px solid $gray-7;
  box-shadow: 0px 2px 4px -2px #1018280F, 0px 4px 8px -2px #1018281A;
  padding: 21px;
  @include gutter($margin-top-full...);
  @include gutter($margin-bottom-full...);
  @include breakpoint($bp-small) {
    gap: 28px;
  }
  @include breakpoint($bp-med) {
    padding: 28px;
  }
}

// Personalized Account Hub
.ama__personalized-account-hub {
  @extend %quick-links-hub;
}

// Logged out quick links
.ama__quick-links-hub {
  @extend %quick-links-hub;

  &__title {
    align-self: stretch;
    color: $black;
    @include type($kepler-std, $font-weight-semibold);
    font-style: normal;
    line-height: normal;
    text-decoration: none;
    @include font-size($h2-font-sizes);        
  }
}

// Personalized Account Info
.ama__personalized-account-info {
  display: flex;
  gap: $gap-xs;
  flex-direction: column;

  @include breakpoint($bp-small) {
    gap: $gap-md;
    flex-direction: row;
    align-items: center;
  }

  &__card {
    &__image {
      width: $card-width;
    }
  }

  &__profile {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: $gap-sm;
  }

  &__name {
    @include type($myriad-pro, $font-weight-bold);
    line-height: normal;
    font-size: 20px;
    @include breakpoint($bp-small) {
      font-size: 24px;
    }
  }
  
  &__subtitle {
    @include type($myriad-pro, $font-weight-light);
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: $gray-64;
    display: flex;
    flex-direction: column;
    gap: $gap-xs;
    font-size: 14px;
    @include breakpoint($bp-small) {
      font-size: 16px;
    }

    @include breakpoint($bp-small) {
      flex-direction: row;
      align-items: center;
    }

    &__divider {
      display: none;
      color: $gray-20;
      @include gutter($padding-left-quarter...);
      @include gutter($padding-right-quarter...);

      @include breakpoint($bp-small) {
        display: block;
      }
    }
  }
}

// Personalized Quick Links
.ama__personalized-quick-links {
  display: flex;
  flex-direction: column;
  gap: $gap-md;

  a {
    text-decoration: none;
  }

  @include breakpoint($bp-large) {
    flex-direction: row;
  }

  &__primary {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: $gap-sm;
    $this: &;

    &--span-2 {
      grid-column: span 2;
    }

    @include breakpoint($bp-med) {
      display: flex;
    }

    @include breakpoint($bp-large) {
      flex: 1 1 ($primary-quick-link-base * 4) + ($gap-md * 3);
      gap: $gap-md;
    }

    &__item {
      @extend %item;
      width: 100%;
      min-width: math.div($primary-quick-link-base-min-mobile, 2px);
      min-height: math.div($primary-quick-link-base-min-mobile, 2px);
      padding: $gap-sm;
      display: flex;
      flex-direction: column;
      justify-content: flex-start;
      align-items: center;
      gap: $gap-sm;
      border-radius: 8px;
      border: 1px solid $divider-line-gray;
      text-align: center;

      @include breakpoint($bp-med) {
        min-height: $primary-quick-link-base;
        min-width: $primary-quick-link-base-min;
      }

      &--compact {
        display: flex;
        justify-content: flex-start;        
        @include breakpoint($bp-med) {
          min-width: 100px;
        }

        min-height: 100px;
        gap: $gap-compact;
      }

      &:hover {
        background-color: $homepagePurple;
        border: 1px solid $homepagePurple;
      }

      &:active {
        background-image: linear-gradient(rgb(0 0 0 / 40%) 0 0);
      }

      &:focus-visible {
        outline: 2px solid $tab-focus-blue;
        outline-offset: 4px;
      }

      &:hover #{$this}__icon-background {
        background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" width="85" height="85" viewBox="0 0 85 85" fill="none"><circle cx="42.5" cy="42.5" r="42.5" fill="%2346166B" fill-opacity="0.25"/></svg>');
      }

      &:hover #{$this}__label {
        color: $white;
      }

      @each $name in $quicklink-icons {
        &:hover .quick-link--icon--#{$name} {
          background: url("../icons/svg/quick-links/icon-#{$name}-white.svg");
          background-size: 24px;
          width: 24px;
          height: 24px;

          @include breakpoint($bp-xs) {
            background-size: 44px;
            width: 44px;
            height: 44px;
          }

        }

        &:hover .quick-link--icon--#{$name}--compact {
          background: url("../icons/svg/quick-links/icon-#{$name}-white.svg");
          background-size: 24px;
          width: 24px;
          height: 24px;
        }
      }
    }

    &__icon-background {
      flex-shrink: 0;
      background-size: contain;
      background-repeat: no-repeat;
      background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 85 85" fill="none"><circle cx="42.5" cy="42.5" r="42.5" fill="white"/><circle cx="42.5" cy="42.5" r="42.5" fill="%238641BC" fill-opacity="0.1"/></svg>');
      display: flex;
      justify-content: center;
      align-items: center;
      width: 45px;
      height: 45px;

      @include breakpoint($bp-small) {
        width: 80px;
        height: 80px;
      }

      @include breakpoint($bp-med) {
        width: 85px;
        height: 85px;
      }

      &--compact {
        width: 45px;
        height: 45px;
      }
    }

    &__label {
      @extend %label;
    }
  }

  &__secondary {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    flex: 1.5 1 30%;
    min-width: $primary-quick-link-base-min-mobile, 2;

    @include breakpoint($bp-small) {
      min-width: $primary-quick-link-base;
    }

    &__item {
      @extend %item;
      display: flex;
      min-height: 44px;
      justify-content: space-between;
      align-items: center;
      align-self: stretch;
      border-bottom: 1px solid $divider-line-gray;

      &:hover {
        text-decoration: underline;
      }

      &:focus-visible {
        outline: 2px solid $tab-focus-blue;
        outline-offset: 4px;
        z-index: 1;
        position: relative;
      }

      &:last-child {
        border-bottom: none;
      }
    }

    &__label {
      @extend %label;
      padding: 8px
    }
  }
}